/*
f(x) = x + y where x: ℝ
                    where
                    y: ℝ : a scalar
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;

    double y;
    template<typename REAL>
    REAL f(
        const REAL & x)
    {
        return x + this->y;    
    }
    heartlib(const double & y)
    {

        this->y = y;

    }
};

