function output = heartlib(y)
% output = heartlib(y)
%
%    f(x) = x + y where x: ℝ
%                        where
%                        y: ℝ : a scalar
    assert(numel(y) == 1);

    function [ret] = f(x)
        assert(numel(x) == 1);

        ret = x + y;
    end

    output.f = @f;
    output.y = y;
end

